let getCookie = (details, callBack) => {
    chrome.cookies.get(details, callBack)
};
let getAll = (details, callBack) => {
    chrome.cookies.getAll(details, callBack)
};
let set = (details, callBack) => {
    chrome.cookies.set(details, callBack)
};
let remove = (details, callBack) => {
    chrome.cookies.remove(details, callBack)
};
let getAllCookieStores = (callBack) => {
    cookies.getAllCookieStores(callBack)
};


export default {
    get: getCookie,
    getAll: getAll,
    set: set,
    remove: remove,
    getAllCookieStores: getAllCookieStores
}


