import $ from "./../lib/jquery";
import cookie from "./../lib/cookie";
import pubSub from "./../lib/pubSub";
import R from "ramda";

let $userAuthEl = $('#userAuthBtn');
let leoURL = "https://lingualeo.com/";

let userLogIn = (userId, clickedFlag) => {

    $userAuthEl.text($userAuthEl.data('text-logout'));
    User.userId = userId;

    $.ajax({
        url: serverConf.api.vocabulary + userId,
        type: 'get',
        success: function (data) {

            if(!clickedFlag && !data){
                dropUser();
                return false;
            }

            if (!data) {
                createUser();
                return false;
            }

            User.Data = data.user;

            $('#userImage').removeClass('dn');
            $('#userImage').attr('src', data.user.ava_m);

            $.ajax({
                url: serverConf.api.vocabulary + userId,
                type: 'get',
                success: function (data) {
                    User.Vocabulary = data.vocabulary;
                    pubSub.publish('userDataUpdate:event', User);
                }
            });
        }
    });

};

let userLogOut = () => {

    $userAuthEl.text($userAuthEl.data('text-login'));

    User.userId = '';
    User.Data = '';

    $('#userImage').addClass('dn');
    $('#userImage').attr('src', '');

    chrome.cookies.set({
        name: 'e-chrome-extension-userId',
        url: serverConf.api.userId,
        value: ''
    });

    pubSub.publish('userDataUpdate:event', '');
};


let createUser = () => {
    chrome.tabs.create({ url: leoURL });
};


let dropUser = () => {
  chrome.cookies.set({
      name: 'e-chrome-extension-userId',
      url: serverConf.api.userId,
      value: cookieUserId.value + ''
  });

  $userAuthEl.text($userAuthEl.data('text-login'));
};

let getUser = (clickAction) => {
  chrome.cookies.get({url: leoURL, name: 'userid'}, function (cookieUserId) {

      if(clickAction && !cookieUserId){
          createUser();
          return false;
      }

      chrome.cookies.set({
          name: 'e-chrome-extension-userId',
          url: serverConf.api.userId,
          value: cookieUserId.value + ''
      });

      userLogIn(cookieUserId.value, clickAction);
  });
};

$userAuthEl.click((e) => {
    e.stopPropagation();

    if (User.userId) {
        userLogOut();
    } else {
        getUser('click');
    }
});


// отримую з контролера дані про юзера, так як я їх можу отримати тільки через скрипт який заекзекчений
pubSub.subscribe('userData:event', function (userData) {
    chrome.cookies.get({url: leoURL, name: 'userid'}, function (cookieUserId) {

        console.log(cookieUserId);
        console.log(userData);

        chrome.cookies.set({
            name: 'e-chrome-extension-userId',
            url: serverConf.api.userId,
            value: cookieUserId.value + ''
        });

        //даємо признак того що це від лінгва лео сайта
    });

    pubSub.publish('pushUserDataToController:event', userData);
});


pubSub.subscribe('PageLoaded:event', data => {
    chrome.cookies.get({url: leoURL, name: 'userid'}, function (cookieUserId) {
        PubSub.publish('PageLoadedPopup:event', cookieUserId);
        //даємо признак того що це від лінгва лео сайта
    });

    pubSub.publish('PageLoadedPopup:event', "212");
});


chrome.cookies.get({
    url: serverConf.api.userId,
    name: 'e-chrome-extension-userId'
}, function (cookie) {
    if (R.path(['value'], cookie)) {
        userLogIn(cookie.value);
    } else {
        userLogOut();
    }
});



